'use strict';
const $=s=>document.querySelector(s);
const controls=document.querySelectorAll('[data-score]');
if(controls.length){fetch('assets/results.json').then(r=>{if(!r.ok)throw new Error('results unavailable');return r.json()}).then(data=>{controls.forEach(btn=>btn.addEventListener('click',()=>{controls.forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));const key=btn.dataset.score;document.querySelectorAll('.bar-row').forEach(row=>{const entry=data.scores.find(x=>x.method===row.dataset.method);if(!entry)return;row.querySelector('.bar-fill').style.setProperty('--width',`${entry[key]/5*100}%`);row.querySelector('.bar-value').textContent=entry[key].toFixed(6);});}));}).catch(()=>{controls.forEach(b=>{b.disabled=true;b.title='离线时显示已内嵌的综合成绩';});});}
const op=$('#op-prob'),part=$('#part-prob'),size=$('#part-size');
function recalc(){if(!op||!part||!size)return;const pi=+op.value/100,theta=+part.value/100,s=+size.value*1048576,p=pi*theta;const total=64*p*(s/1024+s/512+100)/1000;$('#op-label').textContent=`${op.value}%`;$('#part-label').textContent=`${part.value}%`;$('#size-label').textContent=`${size.value} MiB`;$('#joint-value').textContent=`${(p*100).toFixed(2)}%`;$('#value-total').textContent=`${total.toFixed(2)} ms`;$('#value-density').textContent=(total/(+size.value)).toFixed(2);}
[op,part,size].filter(Boolean).forEach(e=>e.addEventListener('input',recalc));recalc();
if('IntersectionObserver'in window){const links=[...document.querySelectorAll('.toc a')];const observer=new IntersectionObserver(entries=>{for(const e of entries){if(!e.isIntersecting)continue;links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id));}},{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('.chapter').forEach(e=>observer.observe(e));}
